(7030683, 1067932, 69324, '<td valign="top">Great tones</td>', 'Great tones', '2013-05-01 22:14:49.000000', NULL, 1),
(7030739, 1068062, 109341, '<td valign="top">Focus is clearly on the nose but the extrmely shallow depth of field already loses sharpness by the eyes (which are critical in wildlife shots in my view).  I also feel the light is a bit harsh. Overall good composition, but find the subject uninspired for a Free Study.  5 from me.</td>', 'Focus is clearly on the nose but the extrmely shallow depth of field already loses sharpness by the eyes (which are critical in wildlife shots in my view).  I also feel the light is a bit harsh. Overall good composition, but find the subject uninspired for a Free Study.  5 from me.', '2013-05-02 00:25:40.000000', NULL, 1),
(7030740, 1064102, 109341, '<td valign="top">Poor lighting, distracting composition (branches, grass, twigs), lack of general subject / focus / story.   3 from me.</td>', 'Poor lighting, distracting composition (branches, grass, twigs), lack of general subject / focus / story.   3 from me.', '2013-05-02 00:26:47.000000', NULL, 1),
(7030741, 1062745, 109341, '<td valign="top">Poorly composed, distracting / messy foreground and subject dead in the center. Because it was shot mid-day the entire right side of the animal is burned out.  That sky and clouds had some potential but you lost if with the rest of the frame.   3</td>', 'Poorly composed, distracting / messy foreground and subject dead in the center. Because it was shot mid-day the entire right side of the animal is burned out.  That sky and clouds had some potential but you lost if with the rest of the frame.   3', '2013-05-02 00:29:57.000000', NULL, 1),
(7030742, 1066719, 109341, '<td valign="top">Seems like a blurry (rear-sync flash?) generic family snapshot.   See nothing here worthy more than a 3. sorry.</td>', 'Seems like a blurry (rear-sync flash?) generic family snapshot.   See nothing here worthy more than a 3. sorry.', '2013-05-02 00:31:31.000000', NULL, 1),
