(7032870, 1067880, 97225, '<td valign="top">Oh, these gorgeous horses again! I can never see <strike>too much</strike> enough of them!</td>', 'Oh, these gorgeous horses again! I can never see too much enough of them!', '2013-05-06 08:50:19.000000', NULL, 1),
(7032871, 1068009, 114225, '<td valign="top">Is that color for real? Obviously saturation has been pumped up, but to have so many colors in the shot is amazing!</td>', 'Is that color for real? Obviously saturation has been pumped up, but to have so many colors in the shot is amazing!', '2013-05-06 08:50:48.000000', NULL, 1),
(7032873, 1067732, 114225, '<td valign="top">Great use of long exposure to give this a sense of calm.</td>', 'Great use of long exposure to give this a sense of calm.', '2013-05-06 08:51:17.000000', NULL, 1),
(7032874, 1067864, 114225, '<td valign="top">Wow, it''s excellent that you can see the eggs from this perspective.</td>', 'Wow, it''s excellent that you can see the eggs from this perspective.', '2013-05-06 08:51:45.000000', NULL, 1),
(7032875, 1067353, 114225, '<td valign="top">Love the contrast you have portrayed.</td>', 'Love the contrast you have portrayed.', '2013-05-06 08:53:37.000000', NULL, 1),
(7032877, 1064920, 114225, '<td valign="top">Very nice choice in composition. I really like the tilt.<br/>But why have the heavy vignette? That takes away so much from this image in my opinion.</td>', 'Very nice choice in composition. I really like the tilt.But why have the heavy vignette? That takes away so much from this image in my opinion.', '2013-05-06 08:54:18.000000', NULL, 1),
(7032878, 1067748, 114225, '<td valign="top">Ouch. But why keep his face out of the frame? To me, that is a crucial element.</td>', 'Ouch. But why keep his face out of the frame? To me, that is a crucial element.', '2013-05-06 08:55:25.000000', NULL, 1),
(7032879, 1067915, 114225, '<td valign="top">Great composition, but your focus misses the eye, which make this not quite as good as it could be.</td>', 'Great composition, but your focus misses the eye, which make this not quite as good as it could be.', '2013-05-06 08:56:08.000000', NULL, 1),
(7032880, 1067827, 114225, '<td valign="top">I really like how the background has multiple colors to it.</td>', 'I really like how the background has multiple colors to it.', '2013-05-06 08:56:28.000000', NULL, 1),
(7032881, 1067601, 114225, '<td valign="top">Lovely! I feel like I''m traveling through time and space.</td>', 'Lovely! I feel like I''m traveling through time and space.', '2013-05-06 08:57:01.000000', NULL, 1),
(7032882, 1066747, 114225, '<td valign="top">Wow, this is a killer abstract.</td>', 'Wow, this is a killer abstract.', '2013-05-06 08:57:27.000000', NULL, 1),
(7032883, 1067899, 114225, '<td valign="top">How cool is that? The smoke trying to create a sine wave.</td>', 'How cool is that? The smoke trying to create a sine wave.', '2013-05-06 08:57:50.000000', NULL, 1),
(7032884, 1067711, 114225, '<td valign="top">Very well done perspective image.</td>', 'Very well done perspective image.', '2013-05-06 08:57:59.000000', NULL, 1),
