(7033747, 1067833, 11769, '<td valign="top">something serious indeed</td>', 'something serious indeed', '2013-05-07 15:55:28.000000', NULL, 1),
(7033759, 1068009, 28427, '<td valign="top">You''ve managed making me dream.  What a pleasing photograph.  Beautiful colours of the ocean and the sky.  If this is a holiday picture: must be/have been a dream holiday.  If this your daily environment: to die for!!</td>', 'You''ve managed making me dream.  What a pleasing photograph.  Beautiful colours of the ocean and the sky.  If this is a holiday picture: must be/have been a dream holiday.  If this your daily environment: to die for!!', '2013-05-07 16:11:27.000000', NULL, 1),
(7033761, 1067833, 28427, '<td valign="top">Wonder what they''re gossiping about.  Love the B&amp;W tones, the sharpness.  Brief, love the overall picture.  One of my favourites.</td>', 'Wonder what they''re gossiping about.  Love the B&W tones, the sharpness.  Brief, love the overall picture.  One of my favourites.', '2013-05-07 16:12:38.000000', NULL, 1),
(7033763, 1067451, 28427, '<td valign="top">Please don''t take this the wrong way, but I profoundly envy you for having access to this extraordinary phenomenon.  Photographs of the Aurora Borealis never get low scores from me.  Especially when the overall photograph is well done, like yours.</td>', 'Please don''t take this the wrong way, but I profoundly envy you for having access to this extraordinary phenomenon.  Photographs of the Aurora Borealis never get low scores from me.  Especially when the overall photograph is well done, like yours.', '2013-05-07 16:17:52.000000', NULL, 1),
(7033766, 1064095, 28427, '<td valign="top">The person in front is disturbing/distracting.  But, moving someone taller than you away is not always easy ;)</td>', 'The person in front is disturbing/distracting.  But, moving someone taller than you away is not always easy ;)', '2013-05-07 16:20:49.000000', NULL, 1),
(7033767, 1065550, 28427, '<td valign="top">Crisp where it has to be, bright colours.  But not tempting me to keep looking at it and discover things.</td>', 'Crisp where it has to be, bright colours.  But not tempting me to keep looking at it and discover things.', '2013-05-07 16:22:15.000000', NULL, 1),
(7033793, 1063291, 108580, '<td valign="top">Wonderful composition and colours offsetting the deep dark BG. Pity the JPG compression you used has created noticeable pixelation.</td>', 'Wonderful composition and colours offsetting the deep dark BG. Pity the JPG compression you used has created noticeable pixelation.', '2013-05-07 17:38:21.000000', NULL, 1),
(7033794, 1067922, 108580, '<td valign="top">Photo''s and titles like this deserve a 7. At least :)</td>', 'Photo''s and titles like this deserve a 7. At least :)', '2013-05-07 17:40:11.000000', NULL, 1),
(7033795, 1066717, 108580, '<td valign="top">Them darn Hawaii boats and skies :)</td>', 'Them darn Hawaii boats and skies :)', '2013-05-07 17:40:51.000000', NULL, 1),
(7033798, 1068032, 108580, '<td valign="top">The blend between colour lower half and b&amp;w upper half is compelling, and weird! Most unusual landscape. Have we conquered Mars?</td>', 'The blend between colour lower half and b&w upper half is compelling, and weird! Most unusual landscape. Have we conquered Mars?', '2013-05-07 17:44:24.000000', NULL, 1),
(7033799, 1067493, 28427, '<td valign="top">Your usage of light is splendid</td>', 'Your usage of light is splendid', '2013-05-07 17:45:22.000000', NULL, 1),
(7033800, 1068001, 108580, '<td valign="top">Fresh, especially where seascapes, portraits, landscapes tend to dominate a FS. Held my attention for more than 20 seconds. 8</td>', 'Fresh, especially where seascapes, portraits, landscapes tend to dominate a FS. Held my attention for more than 20 seconds. 8', '2013-05-07 17:45:37.000000', NULL, 1),
(7033801, 1067269, 28427, '<td valign="top">Nice warm colours.  Looks almost like a pointillism painting at some points.</td>', 'Nice warm colours.  Looks almost like a pointillism painting at some points.', '2013-05-07 17:46:31.000000', NULL, 1),
(7033805, 1067881, 108580, '<td valign="top">Looks suspiciously like a new South African mall going up. Only one bloke I know recently doing B&amp;W and works in the construction industry here :) Gritty and grainy, perhaps intended for a recent Grain Challenge? It''s a good fit for such an industrial image with bold sky and wide distortion in the verticals</td>', 'Looks suspiciously like a new South African mall going up. Only one bloke I know recently doing B&W and works in the construction industry here :) Gritty and grainy, perhaps intended for a recent Grain Challenge? It''s a good fit for such an industrial image with bold sky and wide distortion in the verticals', '2013-05-07 17:52:56.000000', NULL, 1),
(7033806, 1067611, 108580, '<td valign="top">Candid goodness.</td>', 'Candid goodness.', '2013-05-07 17:53:24.000000', NULL, 1),
(7033808, 1067959, 108580, '<td valign="top">Perfect open flare BiF caught. Sharp and colourful but not smashed. Enough details in the whites of the neck feathers. A fish in the talons would be nice :)</td>', 'Perfect open flare BiF caught. Sharp and colourful but not smashed. Enough details in the whites of the neck feathers. A fish in the talons would be nice :)', '2013-05-07 17:57:51.000000', NULL, 1),
(7033809, 1067340, 108580, '<td valign="top">Creativity should be rewarded. 7.</td>', 'Creativity should be rewarded. 7.', '2013-05-07 17:59:03.000000', NULL, 1),
(7033810, 1067960, 108580, '<td valign="top">Love the minimalism here.</td>', 'Love the minimalism here.', '2013-05-07 17:59:53.000000', NULL, 1),
(7033811, 1067615, 108580, '<td valign="top">Great portrait and BG.</td>', 'Great portrait and BG.', '2013-05-07 18:00:12.000000', NULL, 1),
(7033812, 1067665, 108580, '<td valign="top">Love the soft pale PP yet still sharp eyes.</td>', 'Love the soft pale PP yet still sharp eyes.', '2013-05-07 18:00:29.000000', NULL, 1),
(7033813, 1067748, 108580, '<td valign="top">Intriguing PJ image. And the meek will congregate in sheepish awe.</td>', 'Intriguing PJ image. And the meek will congregate in sheepish awe.', '2013-05-07 18:01:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7033814, 1067659, 108580, '<td valign="top">Bold shot with the highlights. DPC can kill you for them. I wont. Lovely bright crisp floral image with a great BG and a little hint of a 2nd colour.</td>', 'Bold shot with the highlights. DPC can kill you for them. I wont. Lovely bright crisp floral image with a great BG and a little hint of a 2nd colour.', '2013-05-07 18:02:37.000000', NULL, 1),
(7033816, 1067857, 108580, '<td valign="top">Nice blend of subdued winter tones and harsh last gasp weather. Could be the Free State of South Africa.</td>', 'Nice blend of subdued winter tones and harsh last gasp weather. Could be the Free State of South Africa.', '2013-05-07 18:04:52.000000', NULL, 1),
(7033817, 1067799, 108580, '<td valign="top">Prison Escapee! That why the B&amp;W? To emphasise the arrow patterns?</td>', 'Prison Escapee! That why the B&W? To emphasise the arrow patterns?', '2013-05-07 18:06:28.000000', NULL, 1),
(7033819, 1067720, 108580, '<td valign="top">Good strong elements of Moon, Bridge, Loco''s, Landscape and Caboose.</td>', 'Good strong elements of Moon, Bridge, Loco''s, Landscape and Caboose.', '2013-05-07 18:07:44.000000', NULL, 1),
(7033820, 1067763, 108580, '<td valign="top">I like the synchronised flying team, great moment caught. But it leaves me an empty feeling, why?, what are they doing there? Other than watching for prey as per your title.</td>', 'I like the synchronised flying team, great moment caught. But it leaves me an empty feeling, why?, what are they doing there? Other than watching for prey as per your title.', '2013-05-07 18:09:20.000000', NULL, 1),
(7033821, 1067402, 108580, '<td valign="top">Natural moments in the wild might even attract an 8.</td>', 'Natural moments in the wild might even attract an 8.', '2013-05-07 18:10:12.000000', NULL, 1),
(7033822, 1068066, 108580, '<td valign="top">Not as bold in colour as others I''ve seen but this could be a change of season. Lovely partial symmetrical blur. I think tilted 90 Deg CW?</td>', 'Not as bold in colour as others I''ve seen but this could be a change of season. Lovely partial symmetrical blur. I think tilted 90 Deg CW?', '2013-05-07 18:10:59.000000', NULL, 1),
(7033823, 1067827, 108580, '<td valign="top">Print it! Hang it!</td>', 'Print it! Hang it!', '2013-05-07 18:12:31.000000', NULL, 1),
(7033824, 1067936, 108580, '<td valign="top">Now THAT is a unique perspective of a very old subject. Lutetia has always looked dull and grey to me in images and even when I visited in person but at this angle with that sky this should be snapped up by the post card manufacturers and Paris Tourism! One nit is a slight 1 degree <u>appearance</u> of tilt CW to the right. 9.</td>', 'Now THAT is a unique perspective of a very old subject. Lutetia has always looked dull and grey to me in images and even when I visited in person but at this angle with that sky this should be snapped up by the post card manufacturers and Paris Tourism! One nit is a slight 1 degree appearance of tilt CW to the right. 9.', '2013-05-07 18:14:53.000000', NULL, 1),
(7033825, 1067864, 108580, '<td valign="top">Magical wildlife interaction. Is this that new 2nd hand lens you bought? Wonderful elements, the stick in the beak, the egs, the yellow foot and perfect exposure on the whites, leaving detail.</td>', 'Magical wildlife interaction. Is this that new 2nd hand lens you bought? Wonderful elements, the stick in the beak, the egs, the yellow foot and perfect exposure on the whites, leaving detail.', '2013-05-07 18:16:21.000000', NULL, 1),
(7033826, 1067493, 108580, '<td valign="top">Works for me. Great lighting and colours used on dark skin.</td>', 'Works for me. Great lighting and colours used on dark skin.', '2013-05-07 18:18:15.000000', NULL, 1),
(7033827, 1064113, 108580, '<td valign="top">Wonderful Milky way shot with the last frame getting the Church correctly exposed. The city light pollution has added a brown tint to the sky and I''d try minimise or darken it in Post. 8</td>', 'Wonderful Milky way shot with the last frame getting the Church correctly exposed. The city light pollution has added a brown tint to the sky and I''d try minimise or darken it in Post. 8', '2013-05-07 18:25:14.000000', NULL, 1),
(7033845, 1063126, 76335, '<td valign="top">Brilliant idea, brilliantly executed. In short -- brilliant.</td>', 'Brilliant idea, brilliantly executed. In short -- brilliant.', '2013-05-07 19:00:38.000000', NULL, 1),
(7033846, 1068066, 76335, '<td valign="top">A beautiful wash of pastels, anchored nicely by the darker, heavier column in the center.</td>', 'A beautiful wash of pastels, anchored nicely by the darker, heavier column in the center.', '2013-05-07 19:02:45.000000', NULL, 1),
(7033847, 1067715, 76335, '<td valign="top">The grain really enhances this. Nice lighting. A classic still life.</td>', 'The grain really enhances this. Nice lighting. A classic still life.', '2013-05-07 19:03:46.000000', NULL, 1),
(7033848, 1062745, 76335, '<td valign="top">Nice idea, though the angle and harsh lighting make the cat hard to "read." And what good is a cat that you can''t read?</td>', 'Nice idea, though the angle and harsh lighting make the cat hard to "read." And what good is a cat that you can''t read?', '2013-05-07 19:06:20.000000', NULL, 1),
(7033849, 1067963, 76335, '<td valign="top">Light strikes me as a bit harsh -- easily overlooked, though, as the composition is very strong -- a nice balance of tones and forms.</td>', 'Light strikes me as a bit harsh -- easily overlooked, though, as the composition is very strong -- a nice balance of tones and forms.', '2013-05-07 19:09:45.000000', NULL, 1),
(7033850, 1067405, 76335, '<td valign="top">Lunar!</td>', 'Lunar!', '2013-05-07 19:10:49.000000', NULL, 1),
(7033851, 1067770, 65234, '<td valign="top">Love the light, and that solitary figure adds so much to the feeling of the image, giving it a marvelous sense of scale.  I actually like that he''s in the shadowed part of the scene.  Great detail everywhere.  So well done :-)</td>', 'Love the light, and that solitary figure adds so much to the feeling of the image, giving it a marvelous sense of scale.  I actually like that he''s in the shadowed part of the scene.  Great detail everywhere.  So well done :-)', '2013-05-07 19:11:53.000000', NULL, 1),
(7033852, 1067864, 65234, '<td valign="top">Spectacular capture!  Tells the story so very beautifully.  Can''t imagine how you got such a clear shot from just the right angle, but kudos!</td>', 'Spectacular capture!  Tells the story so very beautifully.  Can''t imagine how you got such a clear shot from just the right angle, but kudos!', '2013-05-07 19:11:57.000000', NULL, 1),
(7033853, 1066717, 65234, '<td valign="top">So very peaceful and beautiful.  Similar composition to some other images I''ve seen here but I can''t vote it down for that.  It''s just too well done.</td>', 'So very peaceful and beautiful.  Similar composition to some other images I''ve seen here but I can''t vote it down for that.  It''s just too well done.', '2013-05-07 19:12:01.000000', NULL, 1),
(7033854, 1067835, 65234, '<td valign="top">What a gorgeous spider!  Greet image; she''s perfectly isolated from the background.  Looks like she is just waiting to grab a passing bug.  I pity the bug!</td>', 'What a gorgeous spider!  Greet image; she''s perfectly isolated from the background.  Looks like she is just waiting to grab a passing bug.  I pity the bug!', '2013-05-07 19:12:08.000000', NULL, 1),
(7033855, 1067402, 65234, '<td valign="top">I will not make a "who" comment.  I will not make a "who" comment.  I will not make a "who" comment.  This is hard with him looking at me like that!</td>', 'I will not make a "who" comment.  I will not make a "who" comment.  I will not make a "who" comment.  This is hard with him looking at me like that!', '2013-05-07 19:12:25.000000', NULL, 1),
(7033856, 1066400, 76335, '<td valign="top">Well, it''s Jo<u>zs</u>ef. Strong environmental.</td>', 'Well, it''s Jozsef. Strong environmental.', '2013-05-07 19:14:06.000000', NULL, 1),
(7033857, 1067774, 76335, '<td valign="top">Quirky telephoto goodness.</td>', 'Quirky telephoto goodness.', '2013-05-07 19:15:02.000000', NULL, 1),
(7033858, 1067714, 65234, '<td valign="top">Aw, a widdle jumping spider.  They''re kinda'' cute, I think.  If you get too close they rear up defensively.  Usually that causes me to apologize and get out of their personal space.  After taking the picture, of course ;-). This little one is a bit shadowed but it''s rather a nice portrait of his face, so I might have tried an even closer crop.</td>', 'Aw, a widdle jumping spider.  They''re kinda'' cute, I think.  If you get too close they rear up defensively.  Usually that causes me to apologize and get out of their personal space.  After taking the picture, of course ;-). This little one is a bit shadowed but it''s rather a nice portrait of his face, so I might have tried an even closer crop.', '2013-05-07 19:16:10.000000', NULL, 1),
(7033862, 1064059, 65234, '<td valign="top">Looks like he''s very determined.  Nicely brought out from the background, though I''m seeing some sharpening haloes on top of his head ... looks like maybe his feet were the focal point and you had to sharpen his head more in PP.  Darn birds just don''t hold still sometimes!</td>', 'Looks like he''s very determined.  Nicely brought out from the background, though I''m seeing some sharpening haloes on top of his head ... looks like maybe his feet were the focal point and you had to sharpen his head more in PP.  Darn birds just don''t hold still sometimes!', '2013-05-07 19:19:07.000000', NULL, 1),
(7033863, 1067718, 76335, '<td valign="top">Looks like... Never mind. An eight for you.</td>', 'Looks like... Never mind. An eight for you.', '2013-05-07 19:19:57.000000', NULL, 1),
